INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'iconic', 'adj.', '/aɪˈkɒnɪk/', '标志性的;符号的;偶像的', 'The Sydney Opera House is an iconic attraction known around the world.', '悉尼歌剧院是举世闻名的标志性景点。', 'Iconic Attractions', 1, 0, 'senior', 'wordlist', 'elective4', 'U2', 'an iconic attraction', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'attraction', 'n.', '/əˈtrækʃn/', '景点;吸引;吸引力', 'The Great Wall is one of the most famous tourist attractions in China.', '长城是中国最著名的旅游景点之一。', 'Iconic Attractions', 2, 0, 'senior', 'wordlist', 'elective4', 'U2', 'a tourist attraction', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'monument', 'n.', '/ˈmɒnjumənt/', '纪念碑;历史遗迹;不朽之作', 'The tall stone monument was built to honour the city''s history.', '这座高大的石碑是为纪念这座城市的历史而建的。', 'Iconic Attractions', 3, 0, 'senior', 'wordlist', 'elective4', 'U2', 'a national monument', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'foundation', 'n.', '/faʊnˈdeɪʃn/', '地基;基础;创建;基金会', 'Workers laid a strong foundation before building the famous tower.', '工人们在建造这座著名的塔之前先打好了坚固的地基。', 'Iconic Attractions', 4, 0, 'senior', 'wordlist', 'elective4', 'U2', 'lay the foundation', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'freedom', 'n.', '/ˈfriːdəm/', '自由;不受……影响的状态', 'The Statue of Liberty stands as a symbol of freedom for the whole nation.', '自由女神像作为整个国家自由的象征而矗立着。', 'Iconic Attractions', 5, 0, 'senior', 'wordlist', 'elective4', 'U2', 'a symbol of freedom', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'liberty', 'n.', '/ˈlɪbəti/', '自由;自由权', 'Visitors climb the Statue of Liberty to enjoy the view over the harbour.', '游客登上自由女神像,欣赏海港上方的景色。', 'Iconic Attractions', 6, 0, 'senior', 'wordlist', 'elective4', 'U2', 'the Statue of Liberty', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'located', 'adj.', '/ləʊˈkeɪtɪd/', '位于;坐落于', 'Located by the sea, the old castle attracts thousands of tourists each year.', '这座古老的城堡坐落在海边,每年吸引成千上万的游客。', 'Iconic Attractions', 7, 0, 'senior', 'wordlist', 'elective4', 'U2', 'located in the south', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'distribution', 'n.', '/ˌdɪstrɪˈbjuːʃn/', '分布;分配;分发', 'The kangaroo has a wide distribution across the whole country.', '袋鼠在整个国家分布很广。', 'Iconic Attractions', 8, 0, 'senior', 'wordlist', 'elective4', 'U2', 'a wide distribution', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'domain', 'n.', '/dəˈmeɪn/', '领域;领土;范围', 'Tourists can see these amazing creatures in their natural domain.', '游客可以在这些奇妙生物的自然领地里见到它们。', 'Iconic Attractions', 9, 0, 'senior', 'wordlist', 'elective4', 'U2', 'in its natural domain', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'equator', 'n.', '/ɪˈkweɪtə(r)/', '赤道', 'Located to the south of the equator, the country has warm weather all year.', '这个国家位于赤道以南,全年气候温暖。', 'Iconic Attractions', 10, 0, 'senior', 'wordlist', 'elective4', 'U2', 'south of the equator', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'fence', 'n.', '/fens/', '栅栏;围栏', 'A low stone fence was built around the ancient site to protect it.', '古遗址周围修建了一道矮石围栏以保护它。', 'Iconic Attractions', 11, 0, 'senior', 'wordlist', 'elective4', 'U2', 'a wooden fence', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'herb', 'n.', '/hɜːb/', '药草;香草;草本植物', 'Local food at the market is cooked with fresh herbs grown nearby.', '市场上的当地食物用附近种植的新鲜香草烹制。', 'Iconic Attractions', 12, 0, 'senior', 'wordlist', 'elective4', 'U2', 'fresh herbs', '美音 /ɜːrb/');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'grand', 'adj.', '/ɡrænd/', '宏大的;壮丽的;盛大的', 'The grand old palace is the most visited building in the capital.', '这座宏伟的古老宫殿是首都参观人数最多的建筑。', 'Iconic Attractions', 13, 0, 'senior', 'wordlist', 'elective4', 'U2', 'a grand building', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'hollow', 'adj.', '/ˈhɒləʊ/', '中空的;空心的', 'The musical instrument is made from a tree branch which is hollow.', '这件乐器是用一根中空的树枝做成的。', 'Iconic Attractions', 14, 0, 'senior', 'wordlist', 'elective4', 'U2', 'a hollow tree', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'horn', 'n.', '/hɔːn/', '号(乐器);角;喇叭', 'Unlike a horn, the wooden instrument has no finger holes.', '和号不同,这件木制乐器没有指孔。', 'Iconic Attractions', 15, 0, 'senior', 'wordlist', 'elective4', 'U2', 'play a horn', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'minister', 'n.', '/ˈmɪnɪstə(r)/', '部长;大臣;外交使节', 'The Prime Minister opened the new museum with a short speech.', '首相用一段简短的讲话为新博物馆揭幕。', 'Iconic Attractions', 16, 0, 'senior', 'wordlist', 'elective4', 'U2', 'the Prime Minister', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'political', 'adj.', '/pəˈlɪtɪkl/', '政治的', 'The grand market was built as part of a larger political plan.', '这座宏大的市场是更大的政治计划的一部分。', 'Iconic Attractions', 17, 0, 'senior', 'wordlist', 'elective4', 'U2', 'a political plan', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'prison', 'n.', '/ˈprɪzn/', '监狱;监禁', 'The old prison on the island is now a popular history museum.', '岛上那座旧监狱如今是一座很受欢迎的历史博物馆。', 'Iconic Attractions', 18, 0, 'senior', 'wordlist', 'elective4', 'U2', 'an old prison', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'sample', 'n.', '/ˈsɑːmpl/', '样本;样品;实例', 'Researchers travelled around the world taking sample photographs of famous sites.', '研究人员环游世界,拍摄著名景点的样本照片。', 'Iconic Attractions', 19, 0, 'senior', 'wordlist', 'elective4', 'U2', 'take sample photographs', '美音 /ˈsæmpl/');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'session', 'n.', '/ˈseʃn/', '一场;一段时间;会议', 'Each guided session at the site lasts about an hour.', '在这处景点,每场导览大约持续一个小时。', 'Iconic Attractions', 20, 0, 'senior', 'wordlist', 'elective4', 'U2', 'a guided session', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'slogan', 'n.', '/ˈsləʊɡən/', '标语;口号', 'The tourism slogan "There''s nothing like Australia" is known everywhere.', '旅游口号“没有什么能与澳大利亚相比”家喻户晓。', 'Iconic Attractions', 21, 0, 'senior', 'wordlist', 'elective4', 'U2', 'a tourism slogan', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'strait', 'n.', '/streɪt/', '海峡', 'The island is separated from the mainland only by a narrow strait.', '这座岛屿仅由一条狭窄的海峡与大陆隔开。', 'Iconic Attractions', 22, 0, 'senior', 'wordlist', 'elective4', 'U2', 'across the strait', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'temporary', 'adj.', '/ˈtemprəri/', '暂时的;短暂的;临时的', 'The tower was first planned as a temporary structure for the fair.', '这座塔起初只是为博览会规划的一座临时建筑。', 'Iconic Attractions', 23, 0, 'senior', 'wordlist', 'elective4', 'U2', 'a temporary home', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'phase', 'n.', '/feɪz/', '阶段;时期', 'After this phase of building, the bridge was finally opened to visitors.', '在这一建造阶段之后,大桥终于向游客开放。', 'Iconic Attractions', 24, 0, 'senior', 'wordlist', 'elective4', 'U2', 'the next phase', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'trunk', 'n.', '/trʌŋk/', '树干;象鼻;大箱子', 'The famous bridge rests on stone columns as thick as tree trunks.', '这座著名的大桥架在像树干一样粗的石柱上。', 'Iconic Attractions', 25, 0, 'senior', 'wordlist', 'elective4', 'U2', 'a tree trunk', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'vibrate', 'v.', '/vaɪˈbreɪt/', '(使)振动;颤动', 'To play the instrument, you blow into one end and vibrate your lips.', '要演奏这件乐器,你要对着一端吹气并振动嘴唇。', 'Iconic Attractions', 26, 0, 'senior', 'wordlist', 'elective4', 'U2', 'vibrate your lips', '美音 /ˈvaɪbreɪt/');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'violence', 'n.', '/ˈvaɪələns/', '暴力;暴行;猛烈', 'The old fort once protected the town from the violence of war.', '这座古老的堡垒曾保护小镇免受战争的暴力侵害。', 'Iconic Attractions', 27, 0, 'senior', 'wordlist', 'elective4', 'U2', 'the violence of the storm', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'violent', 'adj.', '/ˈvaɪələnt/', '暴力的;猛烈的;激烈的', 'Despite their name, the wild creatures are generally not violent towards people.', '尽管名字吓人,这些野生动物对人通常并不凶猛。', 'Iconic Attractions', 28, 0, 'senior', 'wordlist', 'elective4', 'U2', 'violent storms', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'frequency', 'n.', '/ˈfriːkwənsi/', '频率;发生率;次数', 'The boat trips run at a lower frequency during the rainy season.', '雨季期间,这些游船班次的频率较低。', 'Iconic Attractions', 29, 0, 'senior', 'wordlist', 'elective4', 'U2', 'a limited frequency', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'capacity', 'n.', '/kəˈpæsəti/', '容量;能力;容纳力', 'The iconic stadium known as the "Bird''s Nest" has a capacity of 80,000.', '这座被称为“鸟巢”的标志性体育场可容纳八万人。', 'Iconic Attractions', 30, 0, 'senior', 'wordlist', 'elective4', 'U2', 'a capacity of 80,000', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'mammal', 'n.', '/ˈmæml/', '哺乳动物', 'The platypus is a strange mammal that lays eggs like a bird.', '鸭嘴兽是一种奇特的哺乳动物,它像鸟一样产卵。', 'Iconic Attractions', 31, 0, 'senior', 'wordlist', 'elective4', 'U2', 'a primitive mammal', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'nest', 'n.', '/nest/', '巢;鸟窝;窝点', 'The stadium called the "Bird''s Nest" looks like a giant nest made of steel.', '这座名为“鸟巢”的体育场看起来像一个巨大的钢制鸟巢。', 'Iconic Attractions', 32, 0, 'senior', 'wordlist', 'elective4', 'U2', 'the Bird''s Nest', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'hatch', 'v.', '/hætʃ/', '孵化;孵出;策划', 'The eggs hatch after about ten days in the warm nest.', '这些蛋在温暖的巢里大约十天后孵化。', 'Iconic Attractions', 33, 0, 'senior', 'wordlist', 'elective4', 'U2', 'eggs hatch', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'pouch', 'n.', '/paʊtʃ/', '育儿袋;小袋子;荷包', 'A baby kangaroo stays safe and warm in its mother''s pouch.', '小袋鼠待在母亲的育儿袋里,既安全又暖和。', 'Iconic Attractions', 34, 0, 'senior', 'wordlist', 'elective4', 'U2', 'in its mother''s pouch', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'frog', 'n.', '/frɒɡ/', '蛙;青蛙', 'Visitors to the rainforest park can hear frogs singing at night.', '雨林公园的游客在夜里能听到青蛙的鸣叫。', 'Iconic Attractions', 35, 0, 'senior', 'wordlist', 'elective4', 'U2', 'a poisonous frog', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'golf', 'n.', '/ɡɒlf/', '高尔夫球运动', 'Known as the home of golf, Scotland is a perfect place for a relaxing holiday.', '苏格兰被誉为高尔夫的发源地,是放松度假的好去处。', 'Iconic Attractions', 36, 0, 'senior', 'wordlist', 'elective4', 'U2', 'the home of golf', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'dive', 'v.', '/daɪv/', '潜水;跳水;俯冲', 'Visitors to the islands can dive under the clear blue water to see fish.', '到这些岛屿的游客可以潜入清澈的蓝色海水中观赏鱼群。', 'Iconic Attractions', 37, 0, 'senior', 'wordlist', 'elective4', 'U2', 'dive under the water', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'pitch', 'n.', '/pɪtʃ/', '音高;场地;程度', 'The player changes the shape of his mouth in order to change pitch.', '演奏者通过改变口型来改变音高。', 'Iconic Attractions', 38, 0, 'senior', 'wordlist', 'elective4', 'U2', 'change pitch', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'entitle', 'v.', '/ɪnˈtaɪtl/', '使享有权利;给……命名', 'Visitors with a city pass are entitled to enter many attractions for free.', '持有城市通票的游客有权免费进入许多景点。', 'Iconic Attractions', 39, 0, 'senior', 'wordlist', 'elective4', 'U2', 'be entitled to', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'license', 'v.', '/ˈlaɪsns/', '批准;许可;发执照', 'You can only hold a koala in certain licensed zoos run by animal experts.', '你只能在由动物专家经营的特定持证动物园里抱考拉。', 'Iconic Attractions', 40, 0, 'senior', 'wordlist', 'elective4', 'U2', 'licensed zoos', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'sponsor', 'v.', '/ˈspɒnsə(r)/', '赞助;倡议;主办', 'Visitors can sponsor an elephant to help protect its health and freedom.', '游客可以赞助一头大象,帮助保护它的健康和自由。', 'Iconic Attractions', 41, 0, 'senior', 'wordlist', 'elective4', 'U2', 'sponsor an animal', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'straightforward', 'adj.', '/ˌstreɪtˈfɔːwəd/', '简单的;直接的;坦率的', 'Finding the islands is straightforward, and there are boats every hour.', '找到这些岛屿很简单,而且每小时都有船。', 'Iconic Attractions', 42, 0, 'senior', 'wordlist', 'elective4', 'U2', 'a straightforward route', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'getaway', 'n.', '/ˈɡetəweɪ/', '(短途)度假地;逃离', 'The quiet seaside town is a great getaway from the busy city.', '这座安静的海滨小镇是远离繁忙城市的绝佳度假地。', 'Iconic Attractions', 43, 0, 'senior', 'wordlist', 'elective4', 'U2', 'a great getaway', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'trade', 'n.', '/treɪd/', '贸易;交易;行业', 'The grand market mixes the city''s glorious trade history with modern tourism.', '这座宏大的市场将这座城市辉煌的贸易历史与现代旅游融为一体。', 'Iconic Attractions', 44, 0, 'senior', 'wordlist', 'elective4', 'U2', 'a trade history', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'destination', 'n.', '/ˌdestɪˈneɪʃn/', '目的地;终点', 'Thailand is a premier holiday destination, attracting tourists from all over the world.', '泰国是首屈一指的度假目的地,吸引着世界各地的游客。', 'Iconic Attractions', 45, 0, 'senior', 'wordlist', 'elective4', 'U2', 'a holiday destination', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (12, 'construction', 'n.', '/kənˈstrʌkʃn/', '建造;建筑物;结构', 'Just after its construction, many people were strongly against the famous tower.', '这座著名的塔刚建成后,许多人强烈反对它。', 'Iconic Attractions', 46, 0, 'senior', 'wordlist', 'elective4', 'U2', 'under construction', NULL);
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth) VALUES ('e4u2.01', '①过去分词作定语(被动/完成,前置或后置 = 定语从句)', 'A2', 12, '选择性必修四 U2 — 过去分词作定语,表被动或已完成,逻辑主语是动作承受者:前置如 a ruined castle;后置如 a bridge built in 1920(= which was built)。被修饰名词是动作的承受者用 done;若名词主动发出动作则用 doing。', 1, 'elective4', 'U2', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0);
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth) VALUES ('e4u2.02', '②过去分词作状语(被动/完成,句首或句中)', 'A2', 12, '选择性必修四 U2 — 过去分词作状语,其逻辑主语是句子主语,且主语承受该动作(被动)时用 done:Built of stone, the tower has lasted centuries. / Seen from the air, the site looks stunning. 若主语主动发出动作则用 doing。', 2, 'elective4', 'U2', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0);
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth) VALUES ('e4u2.03', '③过去分词作宾语补足语 / 表语(与 doing 对照)', 'A2', 12, '选择性必修四 U2 — have/get sth done(让某事被做完)、see/find/keep sth done(宾语承受动作);作表语如 the gate remained closed(处于被动/完成状态)。宾语或主语主动进行动作时才用 doing。', 3, 'elective4', 'U2', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0);
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U2' AND code='e4u2.01'), 'We visited a ruined castle ____ on a hill above the old town.', 'located', 'locating', 'to locate', 'locate', 'A', 'castle 是被''坐落''的承受者,表状态/被动,后置定语用过去分词 located(= which is located)。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U2' AND code='e4u2.01'), 'The bridge ____ in 1920 is still one of the city''s most iconic sights.', 'building', 'built', 'to build', 'build', 'B', 'bridge 是被''建造''的对象,表被动+完成,后置定语用 built(= which was built)。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U2' AND code='e4u2.01'), 'Tourists love the old streets ____ with grey stone hundreds of years ago.', 'paving', 'to pave', 'paved', 'pave', 'C', 'streets 被''铺'',被动+完成,后置定语用 paved。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U2' AND code='e4u2.01'), 'Inside the museum you can see ancient symbols ____ onto animal bones.', 'carving', 'to carve', 'carve', 'carved', 'D', 'symbols 是被''刻''的对象,被动用 carved。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U2' AND code='e4u2.01'), 'The didgeridoo is made from a tree branch ____ out by nature.', 'hollowed', 'hollowing', 'to hollow', 'hollow', 'A', 'branch 被''掏空'',被动+完成,后置定语用 hollowed。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U2' AND code='e4u2.01'), 'It is a quiet seaside town ____ far from the busy capital.', 'situating', 'situated', 'to situate', 'situate', 'B', 'town 被''坐落'',表状态,后置定语用 situated。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U2' AND code='e4u2.01'), 'The stadium ____ the "Bird''s Nest" can hold eighty thousand people.', 'calling', 'to call', 'called', 'call', 'C', 'stadium 被''称为'',被动用 called(= which is called)。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U2' AND code='e4u2.01'), 'We took photos of the famous gate ____ of white marble.', 'making', 'to make', 'make', 'made', 'D', 'gate 由大理石''制成'',被动用 made(of)。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U2' AND code='e4u2.01'), 'The temple has a long history ____ back to the Tang Dynasty.', 'dating', 'dated', 'to date', 'date', 'A', 'history 主动''追溯'',date back 是主动含义,用现在分词 dating;这里强调''本身向前回溯''的主动延伸,故 dating 才地道。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U2' AND code='e4u2.01'), 'Visitors admired the grand palace ____ by thousands of workers long ago.', 'building', 'built', 'to build', 'build', 'B', 'palace 被''建造'',被动+完成,后置定语用 built。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U2' AND code='e4u2.01'), 'The old prison, now ____ into a museum, draws many curious tourists.', 'turning', 'to turn', 'turned', 'turn', 'C', 'prison 被''改造成'',被动用 turned。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U2' AND code='e4u2.01'), 'The channel ____ through the mountain still controls the river today.', 'cutting', 'to cut', 'cuts', 'cut', 'D', 'channel 被''开凿'',被动+完成,后置定语用过去分词 cut(cut 的过去分词同形)。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U2' AND code='e4u2.01'), 'On the wall are the names of the engineers ____ in the tower''s construction.', 'involved', 'helping', 'to help', 'help', 'A', 'engineers''被卷入/参与''用过去分词 involved 作后置定语(those involved in)。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U2' AND code='e4u2.01'), 'The market sold goods ____ from many countries along the Silk Road.', 'bringing', 'brought', 'to bring', 'bring', 'B', 'goods 被''带来'',被动+完成,后置定语用 brought。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U2' AND code='e4u2.01'), 'We walked along a path ____ with bright flowers on both sides.', 'lining', 'to line', 'lined', 'line', 'C', 'path 被花''镶边/排满'',被动用 lined(be lined with)。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U2' AND code='e4u2.01'), 'The koalas ____ for each session must be in a good state for human contact.', 'selecting', 'to select', 'select', 'selected', 'D', 'koalas 被''挑选'',被动用 selected(= which are selected)。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U2' AND code='e4u2.01'), 'There is a giant fish-shaped construction ____ to control the water flow.', 'designed', 'designing', 'to design', 'design', 'A', 'construction 被''设计'',被动用 designed。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U2' AND code='e4u2.01'), 'The honey ____ in this remote valley is famous all over the world.', 'producing', 'produced', 'to produce', 'produce', 'B', 'honey 被''生产'',被动+完成,后置定语用 produced。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U2' AND code='e4u2.01'), 'It is a UNESCO heritage site ____ for over two thousand years.', 'preserving', 'to preserve', 'preserved', 'preserve', 'C', 'site 被''保护/保存'',被动用 preserved。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U2' AND code='e4u2.01'), 'Tourists enjoy the clear blue water ____ by long sandy beaches.', 'surrounding', 'to surround', 'surround', 'surrounded', 'D', 'water 被沙滩''环绕'',被动用 surrounded(= which is surrounded)。', 2, 20, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U2' AND code='e4u2.02'), '____ of stone, the ancient tower has lasted for many centuries.', 'Built', 'Building', 'To build', 'Build', 'A', '句子主语 tower 是被''建造''的对象(被动),状语用过去分词 Built(= As it was built)。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U2' AND code='e4u2.02'), '____ from the air, the heritage site looks truly stunning.', 'Seeing', 'Seen', 'To see', 'See', 'B', '主语 site 被''看'',被动,状语用 Seen(= When it is seen)。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U2' AND code='e4u2.02'), '____ to the south of the equator, the country enjoys warm weather all year.', 'Locating', 'To locate', 'Located', 'Locate', 'C', '主语 country 被''定位/坐落'',状语用 Located(= As it is located)。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U2' AND code='e4u2.02'), '____ by Chinese culture, many cities now have Chinatowns that attract tourists.', 'Influencing', 'To influence', 'Influence', 'Influenced', 'D', '主语 cities 被''影响'',被动,状语用 Influenced。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U2' AND code='e4u2.02'), '____ as the home of golf, Scotland is a perfect place for a relaxing holiday.', 'Known', 'Knowing', 'To know', 'Know', 'A', '主语 Scotland 被''知晓/誉为'',被动,状语用 Known(be known as)。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U2' AND code='e4u2.02'), '____ by the first European settlers, the Sunday roast is now typical Australian food.', 'Introducing', 'Introduced', 'To introduce', 'Introduce', 'B', '主语 roast 被''引入'',被动,状语用 Introduced。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U2' AND code='e4u2.02'), '____ originally as a temporary structure, the tower was nearly taken down.', 'Planning', 'To plan', 'Planned', 'Plan', 'C', '主语 tower 被''规划'',被动,状语用 Planned。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U2' AND code='e4u2.02'), '____ around 256 BCE, Dujiangyan is still in use as an irrigation system today.', 'Constructing', 'To construct', 'Construct', 'Constructed', 'D', '主语 Dujiangyan 被''建造'',被动+完成,状语用 Constructed。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U2' AND code='e4u2.02'), '____ from this lookout, the whole bay seems to glow in the morning light.', 'Viewed', 'Viewing', 'To view', 'View', 'A', '主语 bay 被''看/观赏'',被动,状语用 Viewed。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U2' AND code='e4u2.02'), '____ by tall mountains on three sides, the old town is hard to reach.', 'Surrounding', 'Surrounded', 'To surround', 'Surround', 'B', '主语 town 被山''环绕'',被动,状语用 Surrounded。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U2' AND code='e4u2.02'), '____ deep in the rainforest, the waterfall is a hidden getaway for hikers.', 'Hiding', 'To hide', 'Hidden', 'Hide', 'C', '主语 waterfall 被''隐藏'',被动,状语用 Hidden。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U2' AND code='e4u2.02'), '____ with bright lights at night, the bridge becomes the city''s main attraction.', 'Lighting', 'To light', 'Light', 'Lit', 'D', '主语 bridge 被灯光''点亮'',被动,状语用 Lit。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U2' AND code='e4u2.02'), '____ as a world heritage site, the old city now welcomes more visitors than ever.', 'Recognised', 'Recognising', 'To recognise', 'Recognise', 'A', '主语 city 被''认定'',被动,状语用 Recognised。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U2' AND code='e4u2.02'), '____ for hundreds of years, these old walls still stand strong today.', 'Standing', 'Used', 'To use', 'Use', 'B', '主语 walls 被''使用'',被动,状语用 Used(注意''standing''主动但语义不搭后续 still stand);最贴切是 Used。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U2' AND code='e4u2.02'), '____ of white marble, the grand gate shines under the bright sun.', 'Making', 'To make', 'Made', 'Make', 'C', '主语 gate 由大理石''制成'',被动,状语用 Made(be made of)。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U2' AND code='e4u2.02'), '____ to protect the wild animals, the park has set up strong fences.', 'Designing', 'To design', 'Design', 'Designed', 'D', '主语 park 被''设计/建立''以保护动物,被动,状语用 Designed。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U2' AND code='e4u2.02'), '____ by immigrants from many lands, the city offers food from all over the world.', 'Shaped', 'Shaping', 'To shape', 'Shape', 'A', '主语 city 被移民''塑造'',被动,状语用 Shaped。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U2' AND code='e4u2.02'), '____ in the heart of the desert, the small town feels far from everywhere.', 'Setting', 'Set', 'To set', 'Sets', 'B', '主语 town 被''置于/坐落'',被动,状语用 Set。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U2' AND code='e4u2.02'), '____ along the coast for miles, the road gives drivers an amazing ocean view.', 'Building', 'To build', 'Built', 'Build', 'C', '主语 road 被''修建'',被动,状语用 Built。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U2' AND code='e4u2.02'), '____ carefully over many years, the gardens have become a famous attraction.', 'Planting', 'To plant', 'Plant', 'Planted', 'D', '主语 gardens 被''栽种/打理'',被动,状语用 Planted。', 2, 20, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U2' AND code='e4u2.03'), 'After the storm, the workers found the temple gate ____ by a fallen tree.', 'blocked', 'blocking', 'to block', 'block', 'A', 'see/find sth done:gate 被树''堵住'',宾补用过去分词 blocked。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U2' AND code='e4u2.03'), 'At night the staff keep the old museum''s heavy doors ____ for safety.', 'locking', 'locked', 'to lock', 'lock', 'B', 'keep sth done:doors 被''锁上'',宾补用 locked。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U2' AND code='e4u2.03'), 'The city wants to have the ancient bridge ____ before the festival begins.', 'repairing', 'to repair', 'repaired', 'repair', 'C', 'have sth done:bridge 被''修好'',宾补用 repaired。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U2' AND code='e4u2.03'), 'When we reached the top, we saw the whole valley ____ in golden light.', 'bathing', 'to bathe', 'bathe', 'bathed', 'D', 'see sth done:valley 被光''沐浴'',宾补用 bathed。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U2' AND code='e4u2.03'), 'Tourists usually want their photos ____ in front of the famous statue.', 'taken', 'taking', 'to take', 'take', 'A', 'want sth done:photos 被''拍'',宾补用 taken。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U2' AND code='e4u2.03'), 'Be careful with the old steps; the entrance often remains ____ after heavy rain.', 'flooding', 'flooded', 'to flood', 'flood', 'B', 'remain + 表语:entrance 处于被''淹''的状态,用过去分词 flooded。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U2' AND code='e4u2.03'), 'The guide had the gates of the palace ____ so visitors could enter.', 'opening', 'to open', 'opened', 'open', 'C', 'have sth done:gates 被''打开'',宾补用 opened。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U2' AND code='e4u2.03'), 'After many years, the once-grand fort now lies ____ and forgotten.', 'ruining', 'to ruin', 'ruin', 'ruined', 'D', 'lie + 表语:fort 处于被''毁''的状态,用 ruined。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U2' AND code='e4u2.03'), 'The koalas are handled only briefly, and visitors find them ____ from too much contact.', 'stressed', 'stressing', 'to stress', 'stress', 'A', 'find sth done:koalas 被''弄得紧张'',宾补用过去分词 stressed。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U2' AND code='e4u2.03'), 'The town keeps its old market square ____ exactly as it was a century ago.', 'preserving', 'preserved', 'to preserve', 'preserve', 'B', 'keep sth done:square 被''保存'',宾补用 preserved。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U2' AND code='e4u2.03'), 'Before the tour, the manager wants the path ____ of any rubbish.', 'clearing', 'to clear', 'cleared', 'clear', 'C', 'want sth done:path 被''清理'',宾补用 cleared。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U2' AND code='e4u2.03'), 'When the lights went out, the whole hall suddenly became ____ in darkness.', 'covering', 'to cover', 'cover', 'covered', 'D', 'become + 表语:hall 被黑暗''笼罩'',用过去分词 covered。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U2' AND code='e4u2.03'), 'The festival organisers had hundreds of lanterns ____ along the river bank.', 'hung', 'hanging', 'to hang', 'hang', 'A', 'have sth done:lanterns 被''挂起'',宾补用过去分词 hung。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U2' AND code='e4u2.03'), 'After the long winter, the mountain gate stays ____ until spring arrives.', 'closing', 'closed', 'to close', 'close', 'B', 'stay + 表语:gate 处于被''关闭''的状态,用 closed。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U2' AND code='e4u2.03'), 'Visitors should get their tickets ____ at the booth before entering the site.', 'checking', 'to check', 'checked', 'check', 'C', 'get sth done:tickets 被''查验'',宾补用 checked。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U2' AND code='e4u2.03'), 'From the boat we watched the cliffs slowly ____ by the evening mist.', 'hiding', 'to hide', 'hide', 'hidden', 'D', 'watch sth done:cliffs 被雾''遮住'',宾补用 hidden。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U2' AND code='e4u2.03'), 'The city had its old harbour walls ____ to keep the heritage area safe.', 'strengthened', 'strengthening', 'to strengthen', 'strengthen', 'A', 'have sth done:walls 被''加固'',宾补用 strengthened。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U2' AND code='e4u2.03'), 'During the festival, the ancient temple remained ____ to the public all night.', 'opening', 'opened', 'to open', 'open', 'B', 'remain + 表语:此处表''(由人)被开放'',用过去分词 opened 表被动状态。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U2' AND code='e4u2.03'), 'We found the famous fountain ____ off because of repairs that week.', 'switching', 'to switch', 'switched', 'switch', 'C', 'find sth done:fountain 被''关掉'',宾补用 switched(switch off)。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='elective4' AND unit='U2' AND code='e4u2.03'), 'The guide wants every visitor ____ about the rules before the tour starts.', 'telling', 'to tell', 'tell', 'told', 'D', 'want sb done(被告知):visitor 被''告知'',宾补用过去分词 told。', 2, 20, 'mcq');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (12, 'The Statue of Liberty', 'The Statue of Liberty is one of the most iconic attractions in the United States. Located on a small island in New York Harbour, it was given to the American people by France as a gift of friendship. The grand statue, made of metal sheets over an iron frame, was finished in 1886. It shows a woman holding a torch high in one hand, and it has become a worldwide symbol of freedom and liberty. For millions of people arriving by ship long ago, the statue was the first thing they saw, and it gave them hope of a new life. Today, visitors can take a boat to the island and climb the steps inside the statue to enjoy the view over the harbour. The site is preserved with great care, so that people from all over the world can still admire this famous symbol.', '说明·自由女神像', 145, '[{"q":"Where does the Statue of Liberty stand?","answer":"A","options":["On a small island near New York City.","In the centre of Paris.","On top of a high mountain.","Inside a large museum."],"explanation":"原文 ''Located on a small island in New York Harbour'' 的转述。"},{"q":"Why was the statue important to people arriving by ship?","answer":"B","options":["It told them the weather.","Seeing it first filled the newcomers with hope for a fresh start.","It sold them food and water.","It was a place to stay overnight."],"explanation":"原文 ''the first thing they saw… gave them hope of a new life'' 的转述。"},{"q":"What can visitors do at the site today?","answer":"A","options":["Climb the steps and look out over the harbour.","Buy the statue.","Live inside the torch.","Move the statue to another country."],"explanation":"原文 ''climb the steps inside the statue to enjoy the view over the harbour'' 的转述。"}]'::jsonb, '[{"word":"liberty","cn":"自由"},{"word":"located","cn":"位于"},{"word":"iconic","cn":"标志性的"}]'::jsonb, 2, 'elective4', 'U2');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (12, 'The Great Wall of China', 'The Great Wall is perhaps the most famous attraction in China. Built over many hundreds of years, it stretches for thousands of kilometres across mountains, deserts and green valleys. The wall was not made all at once. Different parts were constructed by different states, and later they were joined together to form one long line of defence. Made of stone, brick and earth, the wall protected the people from violent attacks from the north. Along the top there were watchtowers, where soldiers could light fires to warn others of danger. Today, the Great Wall no longer keeps anyone out, but it draws visitors from every corner of the world. Many people say that climbing even a short section is hard work, yet the view from the top is well worth the effort. Recognised as a world heritage site, the wall reminds us of the skill and patience of those who built it long ago.', '说明·长城', 154, '[{"q":"How was the Great Wall created?","answer":"B","options":["It was finished in a single year.","Different parts were built and later joined into one line.","It was carved from one huge rock.","It grew naturally over time."],"explanation":"原文 ''Different parts were constructed… joined together to form one long line'' 的转述。"},{"q":"What were the watchtowers used for?","answer":"C","options":["Selling food to travellers.","Storing water for farms.","Lighting fires to warn people of danger.","Holding sports events."],"explanation":"原文 ''soldiers could light fires to warn others of danger'' 的转述。"},{"q":"What does the wall remind people of today?","answer":"D","options":["The wealth of modern cities.","The best time to grow crops.","The number of tourists each year.","How skilful and patient the people who built it were."],"explanation":"末句 ''reminds us of the skill and patience of those who built it'' 的转述。"}]'::jsonb, '[{"word":"violent","cn":"猛烈的"},{"word":"construct","cn":"建造"},{"word":"heritage","cn":"遗产"}]'::jsonb, 2, 'elective4', 'U2');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (12, 'The Sydney Opera House', 'Few buildings in the world are as easy to recognise as the Sydney Opera House. Located by the water in one of Australia''s busiest harbours, it has a roof shaped like white sails or shells, which seem to catch the wind. The grand building was designed by an architect from Denmark, and its construction was far from straightforward. The work took many more years than planned, and it cost much more money than expected. Some people doubted it would ever be finished. When it finally opened in 1973, however, it quickly became an iconic symbol not just of the city but of the whole country. Inside, there are concert halls where music is performed almost every night. Outside, visitors love to take photos with the white roof behind them. Today the Opera House is one of the most photographed attractions on Earth, and it shows how a bold idea can change the face of a city forever.', '说明·悉尼歌剧院', 157, '[{"q":"What is special about the roof of the Opera House?","answer":"A","options":["Its white curves look like sails catching the wind.","It is painted bright red.","It can be moved by hand.","It is made entirely of glass."],"explanation":"原文 ''a roof shaped like white sails or shells'' 的转述。"},{"q":"What does the text say about building the Opera House?","answer":"B","options":["It was quick and cheap.","It took longer and cost more than expected.","It needed no money at all.","It was built in one weekend."],"explanation":"原文 ''took many more years than planned… cost much more money than expected'' 的转述。"},{"q":"What lesson does the writer draw from the Opera House?","answer":"C","options":["Old buildings are always better.","Music halls should be small.","One daring plan can reshape a whole city for good.","Tourists should stay away from it."],"explanation":"末句 ''a bold idea can change the face of a city forever'' 的转述。"}]'::jsonb, '[{"word":"straightforward","cn":"简单的"},{"word":"construction","cn":"建造"},{"word":"grand","cn":"宏大的"}]'::jsonb, 2, 'elective4', 'U2');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (12, 'The Eiffel Tower', 'The Eiffel Tower is the most famous landmark in France and one of the most visited monuments in the world. But it was not always so loved. When it was first proposed in the 1880s, many people were strongly against it. They claimed that such a tall iron structure would destroy the beauty of the city''s skyline. The chief engineer replied that the tower was needed to show the great efforts of the French people and the progress of modern science. In the end, the tower was built in time for a great fair held in the city. Planned at first as a temporary structure, it was meant to be taken down after twenty years. However, it proved far too useful as a tall tower for sending radio signals, so it was allowed to stay. Little by little, people came to love it, and today the tower stands as a proud symbol of the whole country.', '说明·埃菲尔铁塔', 156, '[{"q":"How did many people feel about the tower at first?","answer":"D","options":["They loved it immediately.","They did not notice it.","They wanted it to be taller.","They strongly disliked the idea."],"explanation":"原文 ''many people were strongly against it'' 的转述。"},{"q":"Why was the tower not taken down after twenty years?","answer":"A","options":["It was useful for sending radio signals.","There was no money to remove it.","It had already fallen down.","No one remembered it was there."],"explanation":"原文 ''too useful as a tall tower for sending radio signals'' 的转述。"},{"q":"How do people feel about the tower today?","answer":"B","options":["They still want it removed.","They are proud of it as a national symbol.","They think it is too short.","They have forgotten about it."],"explanation":"末句 ''stands as a proud symbol of the whole country'' 的转述。"}]'::jsonb, '[{"word":"monument","cn":"纪念碑;历史遗迹"},{"word":"temporary","cn":"暂时的"},{"word":"propose","cn":"提议"}]'::jsonb, 2, 'elective4', 'U2');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (12, 'Dujiangyan: An Ancient Wonder', 'Dujiangyan is a remarkable example of ancient engineering, and it is still in use today after more than two thousand years. Long ago, the people who lived along the banks of the Min River suffered from yearly floods. A wise governor studied the problem with great care and led a team to solve it. They built a long wall in the river to send part of the water in a different direction. Then they cut a channel through a nearby mountain so that the extra water could flow away safely. After the system was finished, the terrible floods stopped. What is more, the redirected water was used to water the fields, and the region became one of the richest farming areas in the country. If you visit today, you will see an unusual stone construction that looks like a fish''s mouth. Recognised as a heritage site, Dujiangyan has protected farms and prevented floods for over twenty centuries.', '说明·都江堰', 157, '[{"q":"What problem did the local people face long ago?","answer":"C","options":["Too little rain for their crops.","Attacks from wild animals.","Floods from the river every year.","A shortage of stone."],"explanation":"原文 ''suffered from yearly floods'' 的转述。"},{"q":"How did the team deal with the extra water?","answer":"D","options":["They stored it in huge tanks.","They sold it to other towns.","They left the water where it was.","They dug a passage in the hillside to let the extra water escape."],"explanation":"原文 ''cut a channel through a nearby mountain so that the extra water could flow away'' 的转述。"},{"q":"What extra benefit did the system bring?","answer":"A","options":["It helped the region become rich farmland.","It created a new mountain.","It stopped all the rain.","It made the river disappear."],"explanation":"原文 ''the redirected water was used to water the fields… one of the richest farming areas'' 的转述。"}]'::jsonb, '[{"word":"construction","cn":"建筑物;建造"},{"word":"heritage","cn":"遗产"},{"word":"channel","cn":"水道;渠"}]'::jsonb, 2, 'elective4', 'U2');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (12, 'The Sound of the Didgeridoo', 'When travellers think of Australia, they often picture beaches and koalas, but one of its most special treasures is a musical instrument called the didgeridoo. It is made from a tree branch which is hollow inside. To play it, a person puts his mouth on one end and blows while making his lips vibrate. Unlike a horn, the didgeridoo has no finger holes at all. To change the pitch, the player must change the shape of his mouth. A skilled player can make sound for a very long time without stopping to breathe. He does this by breathing in through his nose while breathing out through his mouth at the same time. The instrument has been used by the native people of Australia for thousands of years, and its deep, rolling sound is closely connected with their love of the natural world. For many visitors, hearing the didgeridoo played live is an unforgettable part of their trip.', '说明·迪吉里杜管', 157, '[{"q":"What is the didgeridoo made from?","answer":"B","options":["A piece of metal.","A hollow tree branch.","A large shell.","A block of stone."],"explanation":"原文 ''made from a tree branch which is hollow inside'' 的转述。"},{"q":"How does a player change the pitch of the sound?","answer":"C","options":["By pressing finger holes.","By turning a key on the side.","By altering how his mouth is shaped.","By blowing harder only."],"explanation":"原文 ''change the pitch, the player must change the shape of his mouth'' 的转述。"},{"q":"What is the instrument''s sound closely linked with?","answer":"D","options":["The wealth of big cities.","Modern pop music.","The taste of local food.","The native people''s love of nature."],"explanation":"原文 ''closely connected with their love of the natural world'' 的转述。"}]'::jsonb, '[{"word":"hollow","cn":"中空的"},{"word":"vibrate","cn":"振动"},{"word":"pitch","cn":"音高"}]'::jsonb, 2, 'elective4', 'U2');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (12, 'elective4', 'U2', 'A Holiday in Thailand', 'Thailand is a premier holiday (1)____, attracting tourists from all over the world. A major (2)____ of the country is its amazing selection of islands, each with long sandy beaches and clear blue (3)____. Visitors to the beaches can enjoy many activities, including swimming and (4)____ under the water to see colourful fish. Finding the islands is quite (5)____, and there are boats every hour. Be careful, however, not to go during the peak (6)____, unless you want to share the sand with huge crowds. Many tourists also enjoy visiting the north to see the beautiful elephants, a proud (7)____ of the country. Sadly, these animals are in danger, but special parks have been (8)____ up to protect them. Visitors can see these amazing creatures in their natural (9)____, and they can even (10)____ an elephant to help keep it safe and healthy.', 143, 2, '[{"q":"1","answer":"A","options":["destination","machine","mistake","habit"],"explanation":"holiday destination 度假目的地。"},{"q":"2","answer":"B","options":["mistake","attraction","problem","danger"],"explanation":"a major attraction 主要吸引人之处。"},{"q":"3","answer":"C","options":["sound","noise","water","smoke"],"explanation":"clear blue water 清澈的蓝色海水。"},{"q":"4","answer":"D","options":["sleeping","cooking","shopping","diving"],"explanation":"diving under the water 潜水。"},{"q":"5","answer":"A","options":["straightforward","dangerous","expensive","boring"],"explanation":"quite straightforward 相当简单。"},{"q":"6","answer":"B","options":["machine","season","garden","market"],"explanation":"peak season 旺季/高峰季节。"},{"q":"7","answer":"C","options":["price","noise","symbol","error"],"explanation":"a proud symbol 骄傲的象征。"},{"q":"8","answer":"D","options":["pulled","sold","thrown","set"],"explanation":"set up 建立。"},{"q":"9","answer":"A","options":["domain","machine","market","office"],"explanation":"natural domain 自然领地。"},{"q":"10","answer":"B","options":["forget","sponsor","sell","hide"],"explanation":"sponsor an elephant 赞助一头大象。"}]'::jsonb, 1);
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (12, 'elective4', 'U2', 'First Impressions of Australia', 'Last summer I (1)____ to Australia to visit a friend. Before the trip, I had already done some (2)____ on the country. (3)____ to the south of the equator, it is often called "down under". I had read about iconic (4)____ such as the Sydney Opera House, and about cute animals like koalas and kangaroos. After I (5)____, my first impressions were all about food! Australian cooking has been (6)____ by many cultures. The Sunday roast, for example, was first (7)____ by British settlers and is now seen as typical Australian food. Asian cooking, on the other hand, brought in new (8)____ and fresh herbs. After staying for a (9)____, my biggest impression was the rich mix of peoples and cultures that (10)____ up the nation. I will never forget how warm and friendly everyone was.', 136, 2, '[{"q":"1","answer":"C","options":["slept","refused","travelled","failed"],"explanation":"travelled to Australia 去澳大利亚旅行。"},{"q":"2","answer":"D","options":["damage","noise","harm","research"],"explanation":"do some research 做些调查。"},{"q":"3","answer":"A","options":["Located","Selling","Breaking","Losing"],"explanation":"Located to the south 位于……以南。"},{"q":"4","answer":"B","options":["mistakes","attractions","errors","noises"],"explanation":"iconic attractions 标志性景点。"},{"q":"5","answer":"C","options":["left","failed","arrived","slept"],"explanation":"After I arrived 我到达后。"},{"q":"6","answer":"D","options":["broken","sold","lost","influenced"],"explanation":"been influenced by 受……影响。"},{"q":"7","answer":"A","options":["introduced","thrown","sold","hidden"],"explanation":"introduced by settlers 由移民引入。"},{"q":"8","answer":"B","options":["prices","tastes","noises","errors"],"explanation":"new tastes 新口味。"},{"q":"9","answer":"C","options":["second","metre","while","coin"],"explanation":"for a while 一段时间。"},{"q":"10","answer":"D","options":["sell","throw","lose","make"],"explanation":"make up the nation 组成这个国家。"}]'::jsonb, 2);
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (12, 'elective4', 'U2', 'The Grand Bazaar', 'The Grand Bazaar in Istanbul has a long history (1)____ back to 1455. The market that was first built was quite (2)____ compared to today''s huge bazaar. It was (3)____ as part of a larger political plan to improve the city''s economy. At first, the bazaar sold mostly cloth, but it soon (4)____ into selling books, jewellery, furniture and food. By the 17th century, two markets nearby had (5)____ together to form one giant market that became an important part of the Silk Road, (6)____ Europe to Asia. Today, the Grand Bazaar is extremely (7)____, mixing the country''s glorious trade (8)____ with modern tourism. (9)____ by its own past, the market is still growing, with many new shops opening (10)____. Visitors love wandering through its narrow streets, where there is always something interesting to find.', 135, 2, '[{"q":"1","answer":"A","options":["dating","selling","losing","hiding"],"explanation":"dating back to 追溯到。"},{"q":"2","answer":"B","options":["loud","small","rich","wet"],"explanation":"quite small 相当小。"},{"q":"3","answer":"C","options":["lost","sold","built","thrown"],"explanation":"was built as part of 作为……的一部分建造。"},{"q":"4","answer":"D","options":["fell","slept","failed","expanded"],"explanation":"expanded into 扩展到。"},{"q":"5","answer":"A","options":["joined","broken","sold","lost"],"explanation":"joined together 联合在一起。"},{"q":"6","answer":"B","options":["losing","linking","selling","hiding"],"explanation":"linking Europe to Asia 连接欧亚。"},{"q":"7","answer":"C","options":["empty","silent","iconic","broken"],"explanation":"extremely iconic 极具标志性。"},{"q":"8","answer":"D","options":["price","noise","error","history"],"explanation":"trade history 贸易历史。"},{"q":"9","answer":"A","options":["Inspired","Selling","Breaking","Losing"],"explanation":"Inspired by its past 受其历史启发(过去分词状语)。"},{"q":"10","answer":"B","options":["never","nearby","alone","instead"],"explanation":"opening nearby 在附近开张。"}]'::jsonb, 3);
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (12, 'elective4', 'U2', 'A Visit to the Bird''s Nest', 'Last week my family (1)____ the iconic Beijing National Stadium, also known as the "Bird''s Nest". From far away, the building really does look like a giant (2)____ made of steel. Our guide told us that the stadium has a (3)____ of eighty thousand people. (4)____ to host great sporting events, it was finished just before the 2008 Games. The steel bars that form its outer wall were carefully (5)____ to give the building its famous shape. Inside, the seats rise high above the field, and from the top row the players below look very (6)____. We were lucky to join a guided (7)____ that lasted about an hour. Our guide explained how the stadium was (8)____ by thousands of workers over several years. Standing in the middle of the field, I felt very (9)____ to be part of such a famous (10)____. It was a day I will never forget.', 151, 2, '[{"q":"1","answer":"C","options":["lost","sold","visited","failed"],"explanation":"visited the stadium 参观体育场。"},{"q":"2","answer":"D","options":["price","noise","error","nest"],"explanation":"a giant nest 一个巨大的鸟巢。"},{"q":"3","answer":"A","options":["capacity","mistake","noise","danger"],"explanation":"a capacity of 容量为。"},{"q":"4","answer":"B","options":["Selling","Designed","Breaking","Losing"],"explanation":"Designed to host 为举办……而设计(过去分词状语)。"},{"q":"5","answer":"C","options":["lost","sold","shaped","thrown"],"explanation":"carefully shaped 被精心塑形。"},{"q":"6","answer":"D","options":["loud","wet","rich","small"],"explanation":"look very small 看起来很小。"},{"q":"7","answer":"A","options":["session","price","noise","error"],"explanation":"a guided session 一场导览。"},{"q":"8","answer":"B","options":["lost","built","sold","thrown"],"explanation":"was built by workers 由工人建造。"},{"q":"9","answer":"C","options":["bored","afraid","proud","angry"],"explanation":"felt very proud 感到非常自豪。"},{"q":"10","answer":"D","options":["mistake","error","danger","attraction"],"explanation":"such a famous attraction 如此著名的景点。"}]'::jsonb, 4);
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (12, 'elective4', 'U2', 'The Red Beach', 'Far in the north of China lies a strange and beautiful (1)____ called the Red Beach. It is not made of sand, but of a special plant that turns bright red in autumn. (2)____ near the mouth of a wide river, the area looks like a sea of fire when the sun goes down. The site is carefully (3)____, so that the rare plants are not harmed by visitors. Wooden paths have been (4)____ above the wet ground, and people are asked to stay on them at all times. Many kinds of birds build their (5)____ here, and some travel thousands of kilometres to (6)____ their eggs in this safe place. (7)____ from a high lookout, the whole beach seems to glow. The best (8)____ to visit is early autumn, when the colour is at its (9)____. For nature lovers, the Red Beach is a quiet (10)____ from the noise of city life.', 153, 2, '[{"q":"1","answer":"A","options":["attraction","mistake","noise","error"],"explanation":"a beautiful attraction 美丽的景点。"},{"q":"2","answer":"B","options":["Selling","Located","Breaking","Losing"],"explanation":"Located near 位于……附近。"},{"q":"3","answer":"C","options":["lost","sold","protected","thrown"],"explanation":"carefully protected 被精心保护。"},{"q":"4","answer":"D","options":["lost","sold","thrown","built"],"explanation":"have been built 被建造。"},{"q":"5","answer":"A","options":["nests","prices","noises","errors"],"explanation":"build their nests 筑巢。"},{"q":"6","answer":"B","options":["sell","hatch","lose","throw"],"explanation":"hatch their eggs 孵蛋。"},{"q":"7","answer":"C","options":["Selling","Breaking","Seen","Losing"],"explanation":"Seen from a lookout 从瞭望台看(过去分词状语)。"},{"q":"8","answer":"D","options":["price","noise","error","time"],"explanation":"the best time 最佳时间。"},{"q":"9","answer":"A","options":["best","worst","lowest","smallest"],"explanation":"at its best 处于最佳状态。"},{"q":"10","answer":"B","options":["mistake","getaway","noise","danger"],"explanation":"a quiet getaway 安静的度假去处。"}]'::jsonb, 5);
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (12, 'elective4', 'U2', 'Introducing My Hometown', 'I would love to (1)____ visitors to the iconic attractions of my hometown. The first place I always (2)____ is the old stone bridge in the centre of the city. (3)____ over four hundred years ago, it still carries people across the river every day. (4)____ of grey stone, it has lasted through wars and floods. Next, I take guests to a grand temple (5)____ on a quiet hill above the town. (6)____ as a heritage site, it draws many tourists each year. Finally, we walk to the night market, where local food is cooked with fresh (7)____ and sold at low prices. People can (8)____ many different dishes there. Whenever friends come to stay, I am (9)____ that they are entitled to see the very best of my city. For me, sharing these places is the perfect way to (10)____ my pride in where I come from.', 148, 2, '[{"q":"1","answer":"C","options":["sell","lose","introduce","throw"],"explanation":"introduce visitors to 把游客引荐给。"},{"q":"2","answer":"D","options":["lose","throw","sell","recommend"],"explanation":"I always recommend 我总是推荐。"},{"q":"3","answer":"A","options":["Built","Selling","Losing","Breaking"],"explanation":"Built over four hundred years ago 建于四百多年前(过去分词状语)。"},{"q":"4","answer":"B","options":["Selling","Made","Losing","Breaking"],"explanation":"Made of grey stone 由灰石制成(过去分词状语)。"},{"q":"5","answer":"C","options":["losing","selling","located","breaking"],"explanation":"a temple located on a hill 坐落在山上的庙(过去分词作定语)。"},{"q":"6","answer":"D","options":["Selling","Losing","Breaking","Recognised"],"explanation":"Recognised as a heritage site 被认定为遗产地(过去分词状语)。"},{"q":"7","answer":"A","options":["herbs","prices","noises","errors"],"explanation":"fresh herbs 新鲜香草。"},{"q":"8","answer":"B","options":["lose","taste","throw","sell"],"explanation":"taste many dishes 品尝多种菜肴。"},{"q":"9","answer":"C","options":["bored","angry","proud","afraid"],"explanation":"I am proud that 我自豪……。"},{"q":"10","answer":"D","options":["lose","hide","waste","show"],"explanation":"show my pride 展现我的自豪。"}]'::jsonb, 6);
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (12, 'U2 听力·对话 Planning a Trip', '选择性必修四 U2 · dialogue', 3, 'Mia: We only have one day in the city. Which attraction should we see first?
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (12, 'U2 听力·短文 Amazing New Zealand', '选择性必修四 U2 · passage', 2, 'New Zealand is a country located far to the south of the equator.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (12, 'U2 听力·对话 Booking a Tour', '选择性必修四 U2 · dialogue', 3, 'Clerk: Good morning. How can I help you today?
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (12, 'U2 听力·短文 The Story of a Tower', '选择性必修四 U2 · passage', 2, 'The famous iron tower was first planned as a temporary structure for a great fair.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (12, 'U2 听力·对话 Holding a Koala', '选择性必修四 U2 · dialogue', 3, 'Anna: I really want to hold a koala while I''m here. Can I do that anywhere?
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (12, 'U2 听力·短文 Introduce Your City', '选择性必修四 U2 · passage', 2, 'When you introduce an iconic attraction in your city, start with what makes it special.
INSERT INTO public.junior_writing_prompts (grade, topic, title_en, prompt_cn, prompt_en, requirements, min_words, max_words, sample_answer, scoring_rubric, high_sentences, error_pairs, paragraph_template, difficulty, volume, unit) VALUES (12, 'Introduce an Iconic Attraction in Your City(介绍家乡的一处标志性景点)', 'An Iconic Attraction in My City', '假设你叫李华,你校英文网站正在征集“我家乡的标志性景点”短文。请用英语写一篇约100词的短文,介绍你所在城市/家乡的一处标志性景点,内容包括:① 景点名称与位置;② 它的历史或特色(何时建成、为何有名);③ 游客可以在那里体验什么;④ 为什么它值得一游。注意:适当使用过去分词作定语/状语(如 built in…, located in…, known as…)。', 'Suppose you are Li Hua. Your school''s English website is collecting short pieces titled "An Iconic Attraction in My Hometown". Write a passage of about 100 words to introduce one iconic attraction in your city or town, including: 1) its name and location; 2) its history or special features (when it was built and why it is famous); 3) what visitors can experience there; 4) why it is worth visiting. Try to use past participles as attributes or adverbials (e.g. built in…, located in…, known as…).', '["景点名称与位置(… is located in / by …)","历史或特色(Built in …, it is known as / famous for …)","游客体验(Visitors can see / enjoy / walk along …)","推荐理由(It is well worth visiting because …)"]'::jsonb, 70, 100, 'One of the most iconic attractions in my city is the Old Stone Bridge, located in the very centre of the town. Built more than four hundred years ago, it still carries people across the wide river every day. Made of grey stone, it has lasted through floods and wars, and it is now recognised as a protected heritage site. Visitors can walk slowly along the bridge, take photos of the water below, and enjoy the lovely view at sunset. Nearby, a busy night market offers local food cooked with fresh herbs. The bridge is well worth visiting, for it tells the proud story of our city.', '【15 分制】A 档(13-15):五要素齐全、组织有条理、语言准确多样;B 档(10-12):要点较全、少量错误;C 档(7-9):要点偏少、句型简单;D 档(0-6):内容不完整、错误多。', '["Located in the very centre of the town, the Old Stone Bridge is one of our most iconic attractions.","Built more than four hundred years ago, it still carries people across the river every day.","Made of grey stone, it has lasted through floods and wars.","It is well worth visiting, for it tells the proud story of our city."]'::jsonb, '[{"wrong":"The bridge built in 1600 still stand today.","correct":"The bridge built in 1600 still stands today.","note":"主语 the bridge 第三人称单数,谓语动词加 s;built 是过去分词作定语,不是谓语。"},{"wrong":"Located in the centre, it famous for its history.","correct":"Located in the centre, it is famous for its history.","note":"be famous for 需要系动词 is;Located 是过去分词作状语。"},{"wrong":"Make of stone, the gate has lasted centuries.","correct":"Made of stone, the gate has lasted centuries.","note":"主语 gate 被''制成'',状语用过去分词 Made,不用动词原形。"}]'::jsonb, '【家乡景点介绍结构】
INSERT INTO public.junior_grammar_tips (grade, volume, unit, content) VALUES (12, 'elective4', 'U2', '{"title":"过去分词(done)用法速查","intro":"过去分词 = 被动 + 完成。判断口诀:看逻辑主语是不是动作的承受者——是,就用 done(被动);自己主动发出动作才用 doing。过去分词可作定语、状语、宾语补足语和表语。","table":{"headers":["功能","用法 / 例句 / 等价"],"rows":[["作定语(前置)","a ruined castle 一座荒废的城堡(= a castle that is ruined)"],["作定语(后置)","a bridge built in 1920 = a bridge which was built in 1920"],["作状语","Built of stone, the tower has lasted centuries.(= As it was built…)"],["作状语(句首被动)","Seen from the air, the site looks stunning.(= When it is seen…)"],["作宾语补足语","have/get sth done;see/find/keep sth done:keep the doors locked"],["作表语","the gate remained closed 大门一直关着(处于被动/完成状态)"]]},"specialRules":[{"rule":"逻辑主语是承受者 → done(被动);主动发出动作 → doing","mark":"the bridge built(桥被建)vs the workers building(工人在建)"},{"rule":"作状语时,过去分词的逻辑主语必须是句子主语,且主语承受该动作","mark":"Located in the south, the town…(town 被定位)"},{"rule":"have sth done:让/使某事被做(常含''请人做''或''遭遇'')","mark":"had the bridge repaired 把桥修好了"},{"rule":"see/find/keep/want + sth + done:宾语是动作承受者","mark":"found the gate blocked 发现门被堵住"}],"why":["过去分词本身带有''被动''和''完成''两层含义,相当于把一个被动的定语从句或状语从句压缩成一个词;只要被修饰的名词/句子主语是动作的承受者,就用 done,而不是主动的 doing。"],"gaokaoPoints":["句首独立结构:Built/Located/Seen/Given… 后接逗号,主语承受动作时用过去分词,语法填空与读后续写高频。","done 与 doing 的对照:看名词/主语是被动(done)还是主动进行(doing)是判断核心。","have/get sth done、see/find/keep sth done 的宾补结构是写作与单选常考点。"],"examVsReal":[{"exam":"Built in 1920, the bridge is still in use.（考试/书面正式）","real":"The bridge was built in 1920 and it''s still used.","note":"考试爱用过去分词独立结构凝练;口语常拆成两个简单句"},{"exam":"He had his photo taken in front of the statue.（考试强调被动宾补）","real":"He got a photo of himself by the statue.","note":"考试用 have sth done;日常口语换更随意的说法"}]}'::jsonb);
